insert into public.species (id, common_name, scientific_name, category, exploration, exploration_types, description, habitat, diet, curiosity, image_url, source_url, science_source_url, conservation_status, rarity, regions, distribution, where_to_find, fun_facts, keywords) values
  ('perro-domestico', 'Perro doméstico', 'Canis familiaris', 'Mamíferos', 'urbana', array['urban', 'domestic']::text[], 'Mamífero doméstico de gran diversidad de tamaños y aspectos. Sus razas son variantes de una sola especie.', 'Hogares, calles, plazas y otros espacios compartidos con personas.', 'Omnívoro doméstico; su alimentación depende del cuidado humano.', 'La raza se registra manualmente en este prototipo; una foto no permite confirmarla aquí.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Domesticated%20dog.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Domesticated_dog.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Hogares, calles, plazas y otros espacios compartidos con personas.', array['La raza se registra manualmente en este prototipo; una foto no permite confirmarla aquí.']::text[], array['perro', 'dog', 'canis']::text[]),
  ('gato-domestico', 'Gato doméstico', 'Felis catus', 'Mamíferos', 'urbana', array['urban', 'domestic']::text[], 'Felino doméstico. Las razas y variedades no se cuentan como especies diferentes.', 'Hogares, patios, jardines y espacios urbanos.', 'Carnívoro; requiere una alimentación adecuada a su cuidado doméstico.', 'El color o patrón del pelaje no confirma una raza; la variante es opcional y declarada por la persona.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Domestic%20Cat%20(Felis%20catus).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Domestic_Cat_(Felis_catus).jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Hogares, patios, jardines y espacios urbanos.', array['El color o patrón del pelaje no confirma una raza; la variante es opcional y declarada por la persona.']::text[], array['gato', 'cat', 'felis']::text[]),
  ('paloma-bravia', 'Paloma bravía / doméstica', 'Columba livia', 'Aves', 'urbana', array['urban', 'domestic']::text[], 'Ave habitual de las ciudades, con plumajes muy variables en sus poblaciones domésticas y ferales.', 'Edificios, plazas, estaciones y espacios abiertos urbanos.', 'Semillas y otros alimentos disponibles en el entorno.', 'El color o patrón del plumaje no basta para declarar una raza doméstica.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common%20pigeon%20at%20Waterlow%20Park%2C%20London%2001.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Common_pigeon_at_Waterlow_Park,_London_01.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Edificios, plazas, estaciones y espacios abiertos urbanos.', array['El color o patrón del plumaje no basta para declarar una raza doméstica.']::text[], array['paloma', 'pigeon', 'columba']::text[]),
  ('gorrion', 'Gorrión común', 'Passer domesticus', 'Aves', 'urbana', array['urban']::text[], 'Pequeña ave frecuente en entornos urbanos y periurbanos.', 'Calles arboladas, plazas, patios y construcciones.', 'Semillas e insectos, entre otros recursos.', 'Suele buscar alimento en grupos.', 'https://commons.wikimedia.org/wiki/Special:FilePath/House%20sparrow%20male%20in%20Prospect%20Park%20(53532).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:House_sparrow_male_in_Prospect_Park_(53532).jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Calles arboladas, plazas, patios y construcciones.', array['Suele buscar alimento en grupos.']::text[], array['gorrion', 'gorrión', 'sparrow']::text[]),
  ('benteveo', 'Benteveo', 'Pitangus sulphuratus', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Ave reconocible por su pecho amarillo y su llamado fuerte.', 'Parques, jardines, arboledas y bordes de agua.', 'Insectos, frutos y pequeños animales.', 'Puede observarse tanto en la ciudad como en espacios naturales.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Great%20kiskadee%20(70240).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Great_kiskadee_(70240).jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Parques, jardines, arboledas y bordes de agua.', array['Puede observarse tanto en la ciudad como en espacios naturales.']::text[], array['benteveo', 'pitangus', 'kiskadee']::text[]),
  ('zorzal-colorado', 'Zorzal colorado', 'Turdus rufiventris', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Zorzal de vientre rojizo, frecuente en espacios arbolados.', 'Jardines, parques, bosques y arboledas.', 'Frutos e invertebrados.', 'Su canto se oye con frecuencia al amanecer.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rufous-bellied%20thrush%20(Turdus%20rufiventris).JPG?width=900', 'https://commons.wikimedia.org/wiki/File:Rufous-bellied_thrush_(Turdus_rufiventris).JPG', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Jardines, parques, bosques y arboledas.', array['Su canto se oye con frecuencia al amanecer.']::text[], array['zorzal', 'turdus', 'thrush']::text[]),
  ('calandria-grande', 'Calandria grande', 'Mimus saturninus', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Ave de cola larga presente también en ambientes urbanos arbolados.', 'Parques, jardines, matorrales y áreas abiertas.', 'Insectos y frutos.', 'Puede incorporar sonidos de otras aves a sus vocalizaciones.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chalk-browed%20Mockingbird%20(Mimus%20saturninus)%2C%20Pantanal%2C%20Brazil.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Chalk-browed_Mockingbird_(Mimus_saturninus),_Pantanal,_Brazil.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Parques, jardines, matorrales y áreas abiertas.', array['Puede incorporar sonidos de otras aves a sus vocalizaciones.']::text[], array['calandria', 'mimus', 'mockingbird']::text[]),
  ('cotorra-comun', 'Cotorra argentina', 'Myiopsitta monachus', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Loro pequeño de plumaje verde, visible y audible en Buenos Aires.', 'Arboledas urbanas, plazas, parques y ambientes abiertos.', 'Semillas, frutos y brotes.', 'Construye grandes nidos comunales de ramas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Monk%20Parakeet%20(Myiopsitta%20monachus)%20Buenos%20Aires.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Monk_Parakeet_(Myiopsitta_monachus)_Buenos_Aires.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Arboledas urbanas, plazas, parques y ambientes abiertos.', array['Construye grandes nidos comunales de ramas.']::text[], array['cotorra', 'loro', 'parakeet', 'myiopsitta']::text[]),
  ('loro-barranquero', 'Loro barranquero', 'Cyanoliseus patagonus', 'Aves', 'silvestre', array['wild']::text[], 'Loro sudamericano que nidifica en barrancas; no es un avistamiento urbano típico de CABA.', 'Barrancas, estepas y zonas abiertas del sur de Sudamérica.', 'Semillas, frutos y otras partes vegetales.', 'Forma colonias de nidificación en barrancas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cyanoliseus%20patagonus%20-%20Maroparque%2001.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Cyanoliseus_patagonus_-_Maroparque_01.jpg', null, null, 'comun', array['AR']::text[], 'Regiones de Argentina donde está documentada.', 'Barrancas, estepas y zonas abiertas del sur de Sudamérica.', array['Forma colonias de nidificación en barrancas.']::text[], array['loro', 'barranquero', 'cyanoliseus']::text[]),
  ('rata-parda', 'Rata parda / doméstica', 'Rattus norvegicus', 'Mamíferos', 'urbana', array['urban', 'domestic']::text[], 'Roedor asociado a asentamientos humanos en gran parte del mundo.', 'Ambientes urbanos, depósitos y áreas próximas a cursos de agua.', 'Omnívoro oportunista.', 'No conviene manipular animales silvestres ni sus refugios.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rattus%20norvegicus%20.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Rattus_norvegicus_.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Ambientes urbanos, depósitos y áreas próximas a cursos de agua.', array['No conviene manipular animales silvestres ni sus refugios.']::text[], array['rata', 'rattus', 'rat']::text[]),
  ('raton-domestico', 'Ratón doméstico', 'Mus musculus', 'Mamíferos', 'urbana', array['urban', 'domestic']::text[], 'Pequeño roedor que puede vivir cerca de las personas.', 'Edificaciones, jardines y entornos intervenidos.', 'Semillas y diversos alimentos disponibles.', 'Una foto aislada puede no bastar para distinguirlo de otros ratones.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mus%20musculus%202011.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Mus_musculus_2011.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Edificaciones, jardines y entornos intervenidos.', array['Una foto aislada puede no bastar para distinguirlo de otros ratones.']::text[], array['raton', 'ratón', 'mouse', 'mus']::text[]),
  ('lagarto-overo', 'Lagarto overo', 'Salvator merianae', 'Reptiles', 'ambas', array['urban', 'wild']::text[], 'Lagarto grande presente en áreas naturales de la región pampeana, incluso reservas metropolitanas.', 'Pastizales, humedales y reservas urbanas con vegetación.', 'Omnívoro; consume pequeños animales, huevos y frutos.', 'Es mejor observarlo a distancia, sin tocarlo ni alimentarlo.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Argentine%20black%20and%20white%20tegu%20(Salvator%20merianae)%20male%20Vicente%20Lopez.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Argentine_black_and_white_tegu_(Salvator_merianae)_male_Vicente_Lopez.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Pastizales, humedales y reservas urbanas con vegetación.', array['Es mejor observarlo a distancia, sin tocarlo ni alimentarlo.']::text[], array['lagarto', 'overo', 'tegu', 'salvator']::text[]),
  ('tortuga-pintada', 'Tortuga pintada', 'Trachemys dorbigni', 'Reptiles', 'ambas', array['urban', 'wild']::text[], 'Tortuga acuática de Sudamérica registrada en reservas de Buenos Aires.', 'Lagunas, bañados y humedales, incluidos algunos espacios protegidos urbanos.', 'Alimentación variada, con material animal y vegetal.', 'No se debe retirar fauna de lagunas ni liberar mascotas en ellas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trachemys%20dorbigni%20240077434.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Trachemys_dorbigni_240077434.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Lagunas, bañados y humedales, incluidos algunos espacios protegidos urbanos.', array['No se debe retirar fauna de lagunas ni liberar mascotas en ellas.']::text[], array['tortuga', 'trachemys', 'turtle']::text[]),
  ('arana-tigre', 'Araña tigre', 'Argiope argentata', 'Arácnidos', 'ambas', array['urban', 'wild']::text[], 'Araña tejedora de telarañas orbiculares presente en la región.', 'Jardines, vegetación baja y áreas abiertas.', 'Insectos capturados en su red.', 'Observar sin manipular; las fotos no garantizan identificación segura.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ara%C3%B1a%20Tigre%20(Argiope%20argentata).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Araña_Tigre_(Argiope_argentata).jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Jardines, vegetación baja y áreas abiertas.', array['Observar sin manipular; las fotos no garantizan identificación segura.']::text[], array['araña', 'arana', 'argiope', 'spider']::text[]),
  ('escorpion-rayado', 'Escorpión rayado', 'Tityus trivittatus', 'Arácnidos', 'urbana', array['urban']::text[], 'Escorpión registrado en Buenos Aires. La identificación de ejemplares requiere atención especializada.', 'Refugios oscuros en espacios urbanos y periurbanos.', 'Pequeños invertebrados.', 'No tocar ni intentar capturarlo; ante una picadura, acudir a un centro de salud.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tityus%20trivittatus%20-%2002.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Tityus_trivittatus_-_02.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Refugios oscuros en espacios urbanos y periurbanos.', array['No tocar ni intentar capturarlo; ante una picadura, acudir a un centro de salud.']::text[], array['escorpion', 'escorpión', 'alacran', 'alacrán', 'tityus']::text[]),
  ('abeja-melifera', 'Abeja melífera', 'Apis mellifera', 'Insectos', 'ambas', array['urban', 'wild']::text[], 'Abeja social que visita flores en ambientes urbanos y rurales.', 'Jardines, plazas, cultivos y otros sitios con flores.', 'Néctar y polen.', 'Las plantas con flores pueden atraer polinizadores a la ciudad.', 'https://commons.wikimedia.org/wiki/Special:FilePath/AD2009Aug01%20Apis%20mellifera.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:AD2009Aug01_Apis_mellifera.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Jardines, plazas, cultivos y otros sitios con flores.', array['Las plantas con flores pueden atraer polinizadores a la ciudad.']::text[], array['abeja', 'bee', 'apis']::text[]),
  ('hormiga-argentina', 'Hormiga argentina', 'Linepithema humile', 'Insectos', 'ambas', array['urban', 'wild']::text[], 'Hormiga pequeña nativa de Sudamérica, extendida también fuera de su región original.', 'Suelos, jardines, construcciones y otros ambientes.', 'Alimentos variados y sustancias azucaradas.', 'La identificación de una hormiga concreta suele requerir más que una foto.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Linepithema%20Humile.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Linepithema_Humile.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Suelos, jardines, construcciones y otros ambientes.', array['La identificación de una hormiga concreta suele requerir más que una foto.']::text[], array['hormiga', 'ant', 'linepithema']::text[]),
  ('mosquito-aedes', 'Mosquito Aedes aegypti', 'Aedes aegypti', 'Insectos', 'urbana', array['urban']::text[], 'Mosquito de importancia sanitaria. No se debe afirmar su especie solo por una imagen dudosa.', 'Ambientes urbanos, especialmente cerca de recipientes con agua estancada.', 'Las hembras adultas pueden alimentarse de sangre; ambos sexos consumen néctar.', 'Eliminar agua acumulada ayuda a reducir sitios de cría.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aedes%20aegypti%20CDC-Gathany.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Aedes_aegypti_CDC-Gathany.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Ambientes urbanos, especialmente cerca de recipientes con agua estancada.', array['Eliminar agua acumulada ayuda a reducir sitios de cría.']::text[], array['mosquito', 'aedes']::text[]),
  ('cobayo', 'Cobayo', 'Cavia porcellus', 'Mamíferos', 'urbana', array['urban', 'domestic']::text[], 'Roedor doméstico también conocido como conejillo de Indias.', 'Hogares y espacios de cuidado doméstico.', 'Herbívoro.', 'Es un animal doméstico, no una raza de otro roedor.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cavia%20porcellus%20001.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Cavia_porcellus_001.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Hogares y espacios de cuidado doméstico.', array['Es un animal doméstico, no una raza de otro roedor.']::text[], array['cobayo', 'cuy', 'guinea pig', 'cavia']::text[]),
  ('conejo-europeo', 'Conejo europeo / doméstico', 'Oryctolagus cuniculus', 'Mamíferos', 'ambas', array['urban', 'wild', 'domestic']::text[], 'Mamífero que incluye formas domésticas y poblaciones silvestres de la misma especie.', 'Hogares, áreas rurales y poblaciones asilvestradas donde está presente.', 'Herbívoro.', 'Las variedades domésticas no son especies distintas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oryctolagus%20cuniculus.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Oryctolagus_cuniculus.jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Hogares, áreas rurales y poblaciones asilvestradas donde está presente.', array['Las variedades domésticas no son especies distintas.']::text[], array['conejo', 'rabbit', 'oryctolagus']::text[]),
  ('comadreja-overa', 'Comadreja overa', 'Didelphis albiventris', 'Mamíferos', 'ambas', array['urban', 'wild']::text[], 'Marsupial sudamericano que puede aparecer en espacios verdes urbanos.', 'Arboledas, jardines, reservas y otros sitios con refugio.', 'Omnívoro; consume frutos y pequeños animales.', 'Aunque se la llame comadreja, no es un mustélido.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Didelphis%20albiventris%20(Lund%2C%201840)%20(3453282980).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Didelphis_albiventris_(Lund,_1840)_(3453282980).jpg', null, null, 'comun', array['AR']::text[], 'Presente en Argentina; su frecuencia varía según la localidad.', 'Arboledas, jardines, reservas y otros sitios con refugio.', array['Aunque se la llame comadreja, no es un mustélido.']::text[], array['comadreja', 'zarigueya', 'didelfis', 'didelphis']::text[]),
  ('hamster-sirio', 'Hámster sirio', 'Mesocricetus auratus', 'Mamíferos', 'urbana', array['domestic']::text[], 'Pequeño roedor mantenido como animal de compañía.', 'Hogares; su ambiente natural está en zonas áridas de Oriente Medio.', 'Semillas, vegetales y otros alimentos apropiados para la especie.', 'Tiene hábitos predominantemente nocturnos.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20hamster%20front%201.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Golden_hamster_front_1.jpg', null, null, 'comun', array['AR']::text[], 'Animal doméstico presente en distintos países, incluida Argentina.', 'Hogares; su ambiente natural está en zonas áridas de Oriente Medio.', array['Tiene hábitos predominantemente nocturnos.']::text[], array['hámster sirio', 'mesocricetus auratus']::text[]),
  ('huron-domestico', 'Hurón doméstico', 'Mustela furo', 'Mamíferos', 'urbana', array['domestic']::text[], 'Mustélido doméstico criado por personas desde hace siglos.', 'Hogares y espacios de cuidado doméstico.', 'Carnívoro.', 'No debe confundirse con otros mustélidos silvestres.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ferret%202008.png?width=900', 'https://commons.wikimedia.org/wiki/File:Ferret_2008.png', null, null, 'comun', array['AR']::text[], 'Mantenido como animal doméstico en diversos países.', 'Hogares y espacios de cuidado doméstico.', array['No debe confundirse con otros mustélidos silvestres.']::text[], array['hurón doméstico', 'mustela furo']::text[]),
  ('tero', 'Tero', 'Vanellus chilensis', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Ave de espacios abiertos que también puede verse en parques extensos.', 'Pastizales, humedales, campos y espacios verdes abiertos.', 'Invertebrados que busca en el suelo.', 'Defiende con voces fuertes el entorno de su nido.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Southern%20Lapwing%20-%20Indaiatuba%2C%20SP%2C%20BR.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Southern_Lapwing_-_Indaiatuba,_SP,_BR.jpg', 'https://buenosaires.gob.ar/sites/default/files/media/document/2018/02/10/61ad46a5a42ce1d1cc4bc58c9cbfa5ca8e518cbc.pdf', null, 'comun', array['AR']::text[], 'Amplia distribución en Sudamérica, incluida Argentina.', 'Pastizales, humedales, campos y espacios verdes abiertos.', array['Defiende con voces fuertes el entorno de su nido.']::text[], array['tero', 'vanellus chilensis']::text[]),
  ('chimango', 'Chimango', 'Milvago chimango', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Ave rapaz oportunista que utiliza ambientes abiertos y zonas urbanas.', 'Campos, caminos, costas y áreas abiertas urbanas.', 'Carroña, insectos y pequeñas presas.', 'Puede aprovechar recursos alimenticios muy distintos.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chimango%20caracara%20(Daptrius%20chimango%20temucoensis)%20male%20Chiloe.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Chimango_caracara_(Daptrius_chimango_temucoensis)_male_Chiloe.jpg', 'https://buenosaires.gob.ar/sites/default/files/media/document/2018/02/10/61ad46a5a42ce1d1cc4bc58c9cbfa5ca8e518cbc.pdf', null, 'comun', array['AR']::text[], 'Sur de Sudamérica, incluida Argentina.', 'Campos, caminos, costas y áreas abiertas urbanas.', array['Puede aprovechar recursos alimenticios muy distintos.']::text[], array['chimango', 'milvago chimango']::text[]),
  ('gecko-casero', 'Gecko casero tropical', 'Hemidactylus mabouia', 'Reptiles', 'urbana', array['urban']::text[], 'Gecko introducido que puede encontrarse cerca de construcciones.', 'Paredes, edificaciones y refugios urbanos cálidos.', 'Insectos y otros pequeños invertebrados.', 'Suele estar activo al anochecer.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tropical%20house%20gecko%20(Hemidactylus%20mabouia)%20Madden%20Haag.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Tropical_house_gecko_(Hemidactylus_mabouia)_Madden_Haag.jpg', 'https://www.argentina.gob.ar/sites/default/files/lista_oficial_eei_boletin_oficial_con_nombres_comunes_0.pdf', null, 'comun', array['AR']::text[], 'Origen africano; introducido en regiones de América, incluida Argentina.', 'Paredes, edificaciones y refugios urbanos cálidos.', array['Suele estar activo al anochecer.']::text[], array['gecko casero tropical', 'hemidactylus mabouia']::text[]),
