  ('avestruz', 'Avestruz', 'Struthio camelus', 'Aves', 'silvestre', array['wild']::text[], 'Ave africana de gran tamaño incapaz de volar.', 'Sabanas, pastizales y regiones semiáridas.', 'Principalmente plantas; también consume invertebrados.', 'Es el ave viviente de mayor tamaño.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Struthio%20camelus%20portrait%20Whipsnade%20Zoo.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Struthio_camelus_portrait_Whipsnade_Zoo.jpg', null, null, 'notable', '{}'::text[], 'África.', 'Sabanas, pastizales y regiones semiáridas.', array['Es el ave viviente de mayor tamaño.']::text[], array['avestruz', 'struthio camelus']::text[]),
  ('emu', 'Emú', 'Dromaius novaehollandiae', 'Aves', 'silvestre', array['wild']::text[], 'Ave corredora australiana de gran tamaño.', 'Bosques abiertos, sabanas y zonas áridas.', 'Frutos, semillas, brotes e insectos.', 'El macho incuba los huevos y cuida a los polluelos.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Emu%20(Dromaius%20novaehollandiae)%201.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Emu_(Dromaius_novaehollandiae)_1.jpg', null, null, 'notable', '{}'::text[], 'Australia.', 'Bosques abiertos, sabanas y zonas áridas.', array['El macho incuba los huevos y cuida a los polluelos.']::text[], array['emú', 'dromaius novaehollandiae']::text[]),
  ('pavo-real-azul', 'Pavo real azul', 'Pavo cristatus', 'Aves', 'ambas', array['domestic', 'wild']::text[], 'Ave del sur de Asia conocida por el despliegue de la cola del macho.', 'Bosques abiertos, matorrales y áreas cultivadas; también parques bajo cuidado humano.', 'Semillas, frutos, insectos y pequeños animales.', 'La gran rueda visible corresponde a plumas supracaudales, no a la cola verdadera.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Indian%20peafowls%201.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Indian_peafowls_1.jpg', null, null, 'notable', '{}'::text[], 'Sur de Asia; introducido y mantenido en numerosos países.', 'Bosques abiertos, matorrales y áreas cultivadas; también parques bajo cuidado humano.', array['La gran rueda visible corresponde a plumas supracaudales, no a la cola verdadera.']::text[], array['pavo real azul', 'pavo cristatus']::text[]),
  ('gallina-domestica', 'Gallo bankiva / gallina doméstica', 'Gallus gallus', 'Aves', 'ambas', array['domestic', 'wild']::text[], 'Ave asiática cuya forma domesticada incluye numerosas razas de gallinas.', 'Bosques y matorrales del sur y sudeste asiático; formas domésticas en granjas y hogares.', 'Omnívora: semillas, materia vegetal e invertebrados.', 'Las razas domésticas y sus colores pertenecen a la misma especie.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Red%20Junglefowl%20-%20Thailand.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Red_Junglefowl_-_Thailand.jpg', null, null, 'notable', '{}'::text[], 'Especie nativa de Asia; la forma doméstica tiene distribución mundial.', 'Bosques y matorrales del sur y sudeste asiático; formas domésticas en granjas y hogares.', array['Las razas domésticas y sus colores pertenecen a la misma especie.']::text[], array['gallo bankiva / gallina doméstica', 'gallus gallus']::text[]),
  ('loro-hablador', 'Loro hablador', 'Amazona aestiva', 'Aves', 'ambas', array['domestic', 'wild']::text[], 'Loro sudamericano verde con frente azulada y zonas amarillas.', 'Bosques, sabanas arboladas y palmares.', 'Frutos, semillas, flores y brotes.', 'La tenencia responsable debe respetar la normativa y evitar fauna de origen ilegal.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Amazona%20aestiva%20-upper%20body-8a.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Amazona_aestiva_-upper_body-8a.jpg', null, null, 'notable', '{}'::text[], 'Centro de Sudamérica, incluido el norte argentino.', 'Bosques, sabanas arboladas y palmares.', array['La tenencia responsable debe respetar la normativa y evitar fauna de origen ilegal.']::text[], array['loro hablador', 'amazona aestiva']::text[]),
  ('loro-vinoso', 'Loro vinoso', 'Amazona vinacea', 'Aves', 'silvestre', array['wild']::text[], 'Loro del Bosque Atlántico con tonalidad vinosa en el pecho.', 'Bosques atlánticos y pinares nativos.', 'Frutos, semillas y flores.', 'Depende de bosques con árboles grandes para nidificar.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Amazona%20vinacea%20-Parque%20das%20Aves%2C%20Foz%20do%20Iguacu%2C%20Brazil-8a.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Amazona_vinacea_-Parque_das_Aves,_Foz_do_Iguacu,_Brazil-8a.jpg', null, null, 'notable', '{}'::text[], 'Brasil, Paraguay y nordeste de Argentina.', 'Bosques atlánticos y pinares nativos.', array['Depende de bosques con árboles grandes para nidificar.']::text[], array['loro vinoso', 'amazona vinacea']::text[]),
  ('guacamayo-verde', 'Guacamayo verde', 'Ara militaris', 'Aves', 'silvestre', array['wild']::text[], 'Guacamayo principalmente verde con frente roja.', 'Bosques tropicales y laderas arboladas.', 'Frutos, semillas y nueces.', 'Utiliza dormideros y sitios de nidificación en árboles o barrancas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Military%20Macaw%20(Ara%20militaris).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Military_Macaw_(Ara_militaris).jpg', null, null, 'notable', '{}'::text[], 'Poblaciones fragmentadas desde México hasta Sudamérica.', 'Bosques tropicales y laderas arboladas.', array['Utiliza dormideros y sitios de nidificación en árboles o barrancas.']::text[], array['guacamayo verde', 'ara militaris']::text[]),
  ('periquito-lineolado', 'Periquito lineolado', 'Bolborhynchus lineola', 'Aves', 'ambas', array['domestic', 'wild']::text[], 'Pequeño loro americano de plumaje verde con marcas oscuras.', 'Bosques montanos y bordes de bosque.', 'Semillas, frutos y brotes.', 'Las mutaciones de color de cautiverio no son especies distintas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Barred%20Parakeet%2C%20Oxapampa%2C%20Pasco%2C%20Peru%201.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Barred_Parakeet,_Oxapampa,_Pasco,_Peru_1.jpg', null, null, 'notable', '{}'::text[], 'Desde México hasta los Andes de Sudamérica.', 'Bosques montanos y bordes de bosque.', array['Las mutaciones de color de cautiverio no son especies distintas.']::text[], array['periquito lineolado', 'bolborhynchus lineola']::text[]),
  ('agapornis-fischer', 'Agapornis de Fischer', 'Agapornis fischeri', 'Aves', 'ambas', array['domestic', 'wild']::text[], 'Pequeño loro africano también criado como ave de compañía.', 'Sabanas arboladas cercanas al agua.', 'Semillas, frutos y materia vegetal.', 'Es una especie diferente del agapornis de Namibia.', 'https://commons.wikimedia.org/wiki/Special:FilePath/046%20Fischer''s%20lovebird%20in%20the%20Serengeti%20National%20Park%20Photo%20by%20Giles%20Laurent.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:046_Fischer''s_lovebird_in_the_Serengeti_National_Park_Photo_by_Giles_Laurent.jpg', null, null, 'notable', '{}'::text[], 'Norte de Tanzania; criado en otros países.', 'Sabanas arboladas cercanas al agua.', array['Es una especie diferente del agapornis de Namibia.']::text[], array['agapornis de fischer', 'agapornis fischeri']::text[]),
  ('cacatua-blanca', 'Cacatúa blanca', 'Cacatua alba', 'Aves', 'ambas', array['domestic', 'wild']::text[], 'Cacatúa blanca grande originaria de Indonesia.', 'Selvas y bosques de tierras bajas.', 'Frutos, semillas, nueces y brotes.', 'Levanta una amplia cresta blanca cuando está alerta.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cacatua%20alba%20MHNT.ZOO.2010.11.148.17.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Cacatua_alba_MHNT.ZOO.2010.11.148.17.jpg', null, null, 'notable', '{}'::text[], 'Islas del norte de las Molucas, Indonesia.', 'Selvas y bosques de tierras bajas.', array['Levanta una amplia cresta blanca cuando está alerta.']::text[], array['cacatúa blanca', 'cacatua alba']::text[]),
  ('tucan-pico-iris', 'Tucán pico iris', 'Ramphastos sulfuratus', 'Aves', 'silvestre', array['wild']::text[], 'Tucán tropical con pico multicolor.', 'Selvas y bosques húmedos de tierras bajas.', 'Principalmente frutos; también pequeños animales y huevos.', 'Su pico grande es liviano por su estructura interna.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Keel-billed%20Toucan%20(16201157519).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Keel-billed_Toucan_(16201157519).jpg', null, null, 'notable', '{}'::text[], 'Desde el sur de México hasta el norte de Sudamérica.', 'Selvas y bosques húmedos de tierras bajas.', array['Su pico grande es liviano por su estructura interna.']::text[], array['tucán pico iris', 'ramphastos sulfuratus']::text[]),
  ('flamenco-caribeno', 'Flamenco caribeño', 'Phoenicopterus ruber', 'Aves', 'silvestre', array['wild']::text[], 'Flamenco de color rosado intenso de América tropical.', 'Lagunas salinas, costas someras y estuarios.', 'Pequeños organismos acuáticos filtrados con el pico.', 'Es una especie distinta del flamenco austral.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Phoenicopterus%20ruber.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Phoenicopterus_ruber.jpg', null, null, 'notable', '{}'::text[], 'Caribe, península de Yucatán, Galápagos y costas del norte de Sudamérica.', 'Lagunas salinas, costas someras y estuarios.', array['Es una especie distinta del flamenco austral.']::text[], array['flamenco caribeño', 'phoenicopterus ruber']::text[]),
  ('pinguino-rey', 'Pingüino rey', 'Aptenodytes patagonicus', 'Aves', 'silvestre', array['wild']::text[], 'Pingüino grande de islas subantárticas.', 'Costas e islas subantárticas y aguas oceánicas frías.', 'Peces y calamares.', 'No construye nido; mantiene el huevo sobre sus patas bajo un pliegue abdominal.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aptenodytes%20patagonicus.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Aptenodytes_patagonicus.jpg', null, null, 'notable', '{}'::text[], 'Islas subantárticas de los océanos Atlántico, Índico y Pacífico.', 'Costas e islas subantárticas y aguas oceánicas frías.', array['No construye nido; mantiene el huevo sobre sus patas bajo un pliegue abdominal.']::text[], array['pingüino rey', 'aptenodytes patagonicus']::text[]),
  ('pinguino-emperador', 'Pingüino emperador', 'Aptenodytes forsteri', 'Aves', 'silvestre', array['wild']::text[], 'El pingüino viviente de mayor tamaño.', 'Hielo marino y aguas antárticas.', 'Peces, crustáceos y calamares.', 'El macho incuba el huevo durante el invierno antártico.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Emperor%20Penguin%20Manchot%20empereur.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Emperor_Penguin_Manchot_empereur.jpg', null, null, 'notable', '{}'::text[], 'Antártida.', 'Hielo marino y aguas antárticas.', array['El macho incuba el huevo durante el invierno antártico.']::text[], array['pingüino emperador', 'aptenodytes forsteri']::text[]),
  ('pinguino-humboldt', 'Pingüino de Humboldt', 'Spheniscus humboldti', 'Aves', 'silvestre', array['wild']::text[], 'Pingüino de costas templadas influenciadas por la corriente de Humboldt.', 'Costas rocosas, islas y aguas marinas productivas.', 'Peces pequeños y cefalópodos.', 'Nidifica en cuevas, grietas o depósitos de guano.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Humboldt%20Penguin%20(Spheniscus%20humboldti).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Humboldt_Penguin_(Spheniscus_humboldti).jpg', null, null, 'notable', '{}'::text[], 'Costas de Perú y Chile.', 'Costas rocosas, islas y aguas marinas productivas.', array['Nidifica en cuevas, grietas o depósitos de guano.']::text[], array['pingüino de humboldt', 'spheniscus humboldti']::text[]),
  ('espatula-rosada', 'Espátula rosada', 'Platalea ajaja', 'Aves', 'silvestre', array['wild']::text[], 'Ave acuática rosada de pico largo y aplanado.', 'Humedales, lagunas, estuarios y costas someras.', 'Pequeños peces, crustáceos e invertebrados acuáticos.', 'Mueve el pico de lado a lado dentro del agua para localizar alimento.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Roseate%20Spoonbill%20(Platalea%20ajaja).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Roseate_Spoonbill_(Platalea_ajaja).jpg', null, null, 'notable', '{}'::text[], 'América, incluida parte de Argentina.', 'Humedales, lagunas, estuarios y costas someras.', array['Mueve el pico de lado a lado dentro del agua para localizar alimento.']::text[], array['espátula rosada', 'platalea ajaja']::text[]),
  ('bigua', 'Biguá', 'Nannopterum brasilianum', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Ave acuática oscura que bucea para capturar peces.', 'Ríos, lagunas, humedales y costas.', 'Principalmente peces.', 'Suele descansar con las alas extendidas después de bucear.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Neotropic%20cormorant%20(Nannopterum%20brasilianum%20brasilianum)%20in%20flight%20Maipo.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Neotropic_cormorant_(Nannopterum_brasilianum_brasilianum)_in_flight_Maipo.jpg', null, null, 'notable', '{}'::text[], 'América Central y del Sur, incluida Argentina.', 'Ríos, lagunas, humedales y costas.', array['Suele descansar con las alas extendidas después de bucear.']::text[], array['biguá', 'nannopterum brasilianum']::text[]),
  ('carpincho', 'Carpincho', 'Hydrochoerus hydrochaeris', 'Mamíferos', 'ambas', array['urban', 'wild']::text[], 'Roedor semiacuático de gran tamaño, frecuente en humedales y márgenes de ríos de Sudamérica.', 'Humedales, esteros, lagunas, riberas y pastizales cercanos al agua.', 'Herbívoro: consume pastos, plantas acuáticas y vegetación ribereña.', 'Vive en grupos y suele pasar buena parte del día cerca del agua.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hydrochoerus%20hydrochaeris%20216288510.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Hydrochoerus_hydrochaeris_216288510.jpg', null, 'Preocupación menor.', 'comun', array['AR']::text[], 'Sudamérica; humedales y riberas de Argentina.', 'Humedales, esteros, lagunas, riberas y pastizales cercanos al agua.', array['Vive en grupos y suele pasar buena parte del día cerca del agua.']::text[], array['carpincho', 'capybara', 'hydrochoerus', 'waterhog']::text[]),
  ('hornero', 'Hornero', 'Furnarius rufus', 'Aves', 'ambas', array['urban', 'wild']::text[], 'Ave sudamericana conocida por construir nidos de barro con forma de horno.', 'Campos abiertos, zonas rurales, parques, bordes urbanos y arbolado disperso.', 'Insectos, larvas y otros pequeños invertebrados que busca en el suelo.', 'Su nido de barro puede resistir lluvias intensas y se reutiliza por otras especies.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rufous%20Hornero%20(Furnarius%20rufus).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Rufous_Hornero_(Furnarius_rufus).jpg', null, 'Preocupación menor.', 'comun', array['AR']::text[], 'Sudamérica; presente en varias regiones de Argentina.', 'Campos abiertos, zonas rurales, parques, bordes urbanos y arbolado disperso.', array['Su nido de barro puede resistir lluvias intensas y se reutiliza por otras especies.']::text[], array['hornero', 'furnarius', 'rufous', 'ovenbird']::text[]),
  ('zorro-colorado', 'Zorro colorado', 'Lycalopex culpaeus', 'Mamíferos', 'silvestre', array['wild']::text[], 'Cánido sudamericano también conocido como zorro culpeo, de pelaje rojizo y hábitos oportunistas.', 'Estepas, matorrales, zonas andinas, bosques abiertos y ambientes patagónicos.', 'Omnívoro: pequeños mamíferos, aves, huevos, frutos, carroña e insectos.', 'Es uno de los cánidos silvestres más grandes de Sudamérica.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lycalopex%20culpaeus%2001.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Lycalopex_culpaeus_01.jpg', null, 'Preocupación menor.', 'notable', array['AR']::text[], 'Regiones andinas y patagónicas de Sudamérica.', 'Estepas, matorrales, zonas andinas, bosques abiertos y ambientes patagónicos.', array['Es uno de los cánidos silvestres más grandes de Sudamérica.']::text[], array['zorro', 'culpeo', 'colorado', 'lycalopex', 'fox']::text[]),
  ('yaguarete', 'Yaguareté', 'Panthera onca', 'Mamíferos', 'silvestre', array['wild']::text[], 'Gran felino americano, robusto y de mordida poderosa, asociado a selvas, humedales y bosques.', 'Selvas, bosques subtropicales, humedales y áreas con cobertura densa.', 'Carnívoro: caza mamíferos, reptiles y otras presas medianas o grandes.', 'Sus manchas forman rosetas, un patrón útil para identificar individuos.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Panthera%20onca.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Panthera_onca.jpg', null, 'Casi amenazado a nivel global; en varias regiones enfrenta riesgo mayor.', 'especial', array['AR']::text[], 'América; en Argentina sus poblaciones persisten en regiones del norte.', 'Selvas, bosques subtropicales, humedales y áreas con cobertura densa.', array['Sus manchas forman rosetas, un patrón útil para identificar individuos.']::text[], array['yaguarete', 'jaguar', 'panthera', 'onca']::text[]),
  ('condor-andino', 'Cóndor andino', 'Vultur gryphus', 'Aves', 'silvestre', array['wild']::text[], 'Ave carroñera emblemática de los Andes, famosa por su gran envergadura.', 'Cordillera de los Andes, acantilados, sierras y zonas abiertas de altura.', 'Carroña de grandes animales; cumple un rol ecológico como limpiador natural.', 'Planea largas distancias aprovechando corrientes térmicas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%B3ndor%20Andino.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Cóndor_Andino.jpg', null, 'Vulnerable; revisar la categoría local para planes de conservación.', 'especial', array['AR']::text[], 'Cordillera de los Andes y sierras de Sudamérica occidental.', 'Cordillera de los Andes, acantilados, sierras y zonas abiertas de altura.', array['Planea largas distancias aprovechando corrientes térmicas.']::text[], array['condor', 'cóndor', 'vultur', 'gryphus', 'andean']::text[]),
  ('puma', 'Puma', 'Puma concolor', 'Mamíferos', 'silvestre', array['wild']::text[], 'Felino de amplia distribución en América, adaptable a montañas, bosques y estepas.', 'Ambientes muy variados: montañas, bosques, matorrales, estepas y desiertos.', 'Carnívoro: caza herbívoros medianos, roedores y otras presas disponibles.', 'No ruge como los grandes Panthera; emite vocalizaciones más parecidas a maullidos fuertes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/South%20American%20Mountain%20Lion%20Hunting%20Guanaco%2C%20Magallanes%20y%20Ant%C3%A1rtica%20Chilena%2C%20CL%20imported%20from%20iNaturalist%20photo%20419995101.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:South_American_Mountain_Lion_Hunting_Guanaco,_Magallanes_y_Antártica_Chilena,_CL_imported_from_iNaturalist_photo_419995101.jpg', null, 'Preocupación menor a nivel global.', 'especial', array['AR']::text[], 'Amplia distribución americana; presente en diversas ecorregiones argentinas.', 'Ambientes muy variados: montañas, bosques, matorrales, estepas y desiertos.', array['No ruge como los grandes Panthera; emite vocalizaciones más parecidas a maullidos fuertes.']::text[], array['puma', 'cougar', 'mountain', 'lion', 'concolor']::text[]),
  ('mariposa-monarca', 'Mariposa monarca', 'Danaus plexippus', 'Insectos', 'silvestre', array['wild']::text[], 'Mariposa naranja y negra célebre por sus migraciones masivas en Norteamérica.', 'Praderas, jardines, bordes de caminos y sitios con algodoncillo durante su reproducción.', 'Adultos: néctar. Orugas: plantas de algodoncillo.', 'Varias generaciones participan en su ciclo migratorio anual.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Danaus%20plexippus%20(monarch%20butterfly)%203%20(17071317368).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Danaus_plexippus_(monarch_butterfly)_3_(17071317368).jpg', null, 'Pendiente de verificación según población y región.', 'notable', array['AR']::text[], 'América; la migración más conocida ocurre en Norteamérica.', 'Praderas, jardines, bordes de caminos y sitios con algodoncillo durante su reproducción.', array['Varias generaciones participan en su ciclo migratorio anual.']::text[], array['monarca', 'monarch', 'danaus', 'plexippus', 'butterfly']::text[]),
  ('tucan', 'Tucán toco', 'Ramphastos toco', 'Aves', 'silvestre', array['wild']::text[], 'Ave de gran pico anaranjado, presente en bosques, sabanas arboladas y bordes de selva.', 'Bosques abiertos, sabanas arboladas, palmares y bordes de selva.', 'Principalmente frutos; también puede consumir insectos, huevos o pequeños vertebrados.', 'Su pico ayuda a regular la temperatura corporal y alcanzar frutos distantes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Toco%20toucan%20(Ramphastos%20toco).jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Toco_toucan_(Ramphastos_toco).jpg', null, 'Preocupación menor.', 'notable', array['AR']::text[], 'Centro y este de Sudamérica; en Argentina, principalmente el nordeste.', 'Bosques abiertos, sabanas arboladas, palmares y bordes de selva.', array['Su pico ayuda a regular la temperatura corporal y alcanzar frutos distantes.']::text[], array['tucan', 'tucán', 'toucan', 'ramphastos', 'toco']::text[]),
  ('rana-criolla', 'Rana criolla', 'Leptodactylus latrans', 'Anfibios', 'ambas', array['urban', 'wild']::text[], 'Anfibio sudamericano asociado a ambientes húmedos y cuerpos de agua temporarios o permanentes.', 'Lagunas, zanjas, pastizales inundables y áreas cercanas a cursos de agua.', 'Invertebrados y pequeños animales que captura cerca del agua.', 'Puede producir nidos de espuma durante la reproducción.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ke%20-%20Leptodactylus%20latrans%20-%201.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:Ke_-_Leptodactylus_latrans_-_1.jpg', null, 'Preocupación menor.', 'comun', array['AR']::text[], 'Sudamérica; presente en ambientes húmedos de Argentina.', 'Lagunas, zanjas, pastizales inundables y áreas cercanas a cursos de agua.', array['Puede producir nidos de espuma durante la reproducción.']::text[], array['rana', 'criolla', 'leptodactylus', 'latrans', 'frog']::text[]),
  ('pinguino-magallanes', 'Pingüino de Magallanes', 'Spheniscus magellanicus', 'Aves', 'silvestre', array['wild']::text[], 'Pingüino sudamericano que nidifica en colonias costeras del Atlántico y el Pacífico sur.', 'Costas, islas, colonias de nidificación y aguas marinas templado-frías.', 'Peces pequeños, calamares y crustáceos.', 'Excava madrigueras o usa refugios naturales para proteger sus nidos.', 'https://commons.wikimedia.org/wiki/Special:FilePath/4%20Spheniscus%20magellanicus.jpg?width=900', 'https://commons.wikimedia.org/wiki/File:4_Spheniscus_magellanicus.jpg', null, 'Preocupación menor.', 'notable', array['AR']::text[], 'Costas del sur de Sudamérica, incluida la Patagonia argentina.', 'Costas, islas, colonias de nidificación y aguas marinas templado-frías.', array['Excava madrigueras o usa refugios naturales para proteger sus nidos.']::text[], array['pinguino', 'pingüino', 'magallanes', 'spheniscus', 'penguin']::text[]);
